const mails = await api.get("/mails", {});
const items = mails.items || [];
const labels = [...new Set(items.map(m => m.label))];
const refund = items.filter(m => m.label && m.label.includes("환불"));
const ids = [...new Set(refund.map(m => m.customer_id).filter(Boolean))];
const custs = await Promise.all(ids.map(id => api.get("/customers/" + id)));
const gold = custs.filter(c => c.tier === "gold").map(c => ({ id: c.id, name: c.name, tier: c.tier }));
return { labels, refundCount: refund.length, refundCustomerIds: ids, tiers: custs.map(c => ({ id: c.id, tier: c.tier })), gold };

const mails = await api.get("/mails", { label: "refund" });
const items = mails.items || [];
const ids = [...new Set(items.map(m => m.customer_id).filter(Boolean))];
const custs = await Promise.all(ids.map(id => api.get("/customers/" + id)));
const gold = custs.filter(c => c.tier === "gold").map(c => ({ id: c.id, name: c.name, tier: c.tier }));
return { mailCount: items.length, customerIds: ids, tiers: custs.map(c => ({ id: c.id, name: c.name, tier: c.tier })), gold };

